import{_ as s,o as t,c as o,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0069 — Relations résolues dans la réponse publique, et ce qui manque à une collectivité : délégations, pages Élus et Lieux, démarches, flux d'agenda","description":"Extrait de docs/adr/0069-relations-resolues-et-ce-qui-manque-a-une-collectivite.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0069 — Relations résolues dans la réponse publique, et ce qui manque à une collectivité : délégations, pages Élus et Lieux, démarches, flux d'agenda","description":"Extrait de docs/adr/0069-relations-resolues-et-ce-qui-manque-a-une-collectivite.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0069-relations-resolues-et-ce-qui-manque-a-une-collectivite.md","filePath":"developpeurs/adr/0069-relations-resolues-et-ce-qui-manque-a-une-collectivite.md"}`),n={name:"developpeurs/adr/0069-relations-resolues-et-ce-qui-manque-a-une-collectivite.md"};function a(l,e,d,c,r,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0069--relations-résolues-dans-la-réponse-publique-et-ce-qui-manque-à-une-collectivité--délégations-pages-élus-et-lieux-démarches-flux-dagenda" tabindex="-1">ADR-0069 — Relations résolues dans la réponse publique, et ce qui manque à une collectivité : délégations, pages Élus et Lieux, démarches, flux d&#39;agenda <a class="header-anchor" href="#adr-0069--relations-résolues-dans-la-réponse-publique-et-ce-qui-manque-à-une-collectivité--délégations-pages-élus-et-lieux-démarches-flux-dagenda" aria-label="Permalink to &quot;ADR-0069 — Relations résolues dans la réponse publique, et ce qui manque à une collectivité : délégations, pages Élus et Lieux, démarches, flux d&#39;agenda {#adr-0069--relations-résolues-dans-la-réponse-publique-et-ce-qui-manque-à-une-collectivité--délégations-pages-élus-et-lieux-démarches-flux-dagenda}&quot;">​</a></h1><p><strong>Date :</strong> 8 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> lot 15 (partie API), recette du thème Collectivité <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a> (<code>GET /public/resolve</code>), <a href="/teuthis-cms-distribution/developpeurs/adr/0046-profils-d-usage-a-l-installation">ADR-0046</a> (pages de départ d&#39;un profil), <a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a> (limite de débit des routes anonymes)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>La recette du thème Collectivité a relevé quatre manques qu&#39;un front ne peut pas combler seul.</p><ul><li>Un événement de l&#39;agenda cite son lieu par un identifiant. Pour écrire « Salle des fêtes, 1 place de la Mairie » sous l&#39;événement, le front devait deviner l&#39;adresse du lieu, ou n&#39;en rien dire. Les lieux n&#39;ont ni vue liste ni vue détail (corpus <code>ANNUAIRE_LIEUX.docx</code>) : aucune route ne les lisait.</li><li>La fiche d&#39;un-e élu-e porte ses fonctions mais pas ses délégations (« Finances », « Jeunesse et sports »).</li><li>Le corpus ne décrit ni vue liste d&#39;API pour l&#39;annuaire des élus ni pour celui des lieux : l&#39;annuaire se compose à la main avec le bloc « Liste de contenus ». Mais ce bloc est plafonné à six cartes en pleine largeur, et rend les données brutes des fiches, pas ce qu&#39;un annuaire affiche.</li><li>Aucune route ne listait les démarches (formulaires publics) ouvertes d&#39;une organisation, et l&#39;agenda n&#39;offrait que l&#39;<code>.ics</code> d&#39;un événement isolé : pas d&#39;abonnement à tout l&#39;agenda.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Les relations sont résolues dans la réponse publique d&#39;une fiche.</strong></p><ul><li><code>GET /public/resolve</code> (réponse <code>entry</code>) et <code>GET /listings/{clé}</code> portent un champ <code>relations</code> : pour chaque champ <code>relation</code> ou <code>relations</code> <strong>renseigné</strong>, le résumé de la cible — <code>{id, type, title, path, url, address}</code> — pour un champ simple, la liste de ces résumés pour un champ multiple.</li><li>Une cible n&#39;est résolue que si elle serait servie au même visiteur anonyme du même site : <code>public_visibility_clause</code> (statut du workflow, visibilité, fenêtre de publication, exclusions d&#39;index, mutualisation), avec la date de fin de publication de <strong>son</strong> type. Brouillon, restreinte, dépubliée, exclue des index, d&#39;un autre site, d&#39;une autre organisation, d&#39;un autre type que celui que le champ déclare : <code>null</code> pour un champ simple, omise d&#39;une liste, sans rien révéler d&#39;elle.</li><li>Toutes les cibles d&#39;une fiche (ou d&#39;une page de liste) se lisent en <strong>une requête</strong> sur <code>content_entries</code>, après une lecture des types cibles. Un type sans champ relation, ou un champ vide, ne coûte aucune requête. Le lot est borné à 500 identifiants.</li><li>Le résumé ne porte que le titre, l&#39;adresse publique (<code>path</code>, et <code>url</code> si le site a un domaine ; <code>null</code> pour un type « contenu court sans vue détail », comme les lieux) et l&#39;adresse postale du premier champ de géolocalisation de la cible quand il est public et non personnel. Jamais un téléphone, un courriel ni un champ déclaré <code>public=False</code>.</li><li><strong>Fraîcheur : celle de la fiche.</strong> Il n&#39;y a pas de cache serveur (ADR-0016). L&#39;en-tête <code>Cache-Control</code> de <code>/public/resolve</code> et de <code>/listings/{clé}</code> (60 s, <code>app/core/public_cache.py</code>) couvre la réponse entière : un lieu renommé ou dépublié se voit au plus tard une minute après, comme la fiche elle-même. Aucune invalidation croisée n&#39;est à faire.</li></ul><p><strong>2. Le type <code>annuaire_elu</code> gagne un champ répétable <code>delegations</code>.</strong></p><ul><li>Même patron que <code>fonctions</code> : un sous-champ texte <code>intitule</code>, ordonné, public, avec libellé et aide (<code>plugins.annuaire_elus.aide.delegations</code>), juste après <code>fonctions</code>.</li><li>Un Content Type déjà provisionné n&#39;est jamais réécrit (<code>outcome=&quot;kept&quot;</code>) et il n&#39;existe pas de mise à jour de schéma par version de manifeste : les organisations qui ont déjà le plugin reçoivent le champ par la <strong>migration 0051</strong>. Elle ne pose que ce champ, après <code>fonctions</code> (en fin de schéma si <code>fonctions</code> a été retiré), laisse intacts les schémas personnalisés, ignore un champ <code>delegations</code> déjà présent (idempotente) et n&#39;incrémente pas <code>schema_version</code> : le champ est facultatif et l&#39;incrément suspendrait la mutualisation de tous les sites de l&#39;organisation.</li><li>Le retour arrière <strong>refuse</strong> s&#39;il existe une fiche portant des délégations ; sinon il ne retire que le champ posé à l&#39;identique par la migration.</li><li><strong>Décision du Product Owner du 08/10 : seul le courriel d&#39;un élu est public</strong> (avec ses réseaux sociaux, qui restent publics et affichés). <code>telephones</code>, <code>adresse</code>, <code>code_postal</code> et <code>ville</code> passent <code>public=False</code> : retranchés de l&#39;API publique (<code>resolve</code>, listes, <code>data</code> des éléments d&#39;un bloc <code>relation_list</code>, <code>summary</code>), toujours saisissables au back-office. La migration 0051 (renommée <code>0051_delegations_et_coordonnees_des_elus</code>) pose aussi <code>&quot;public&quot;: false</code> sur ces quatre champs dans le schéma stocké des types <code>annuaire_elu</code> existants (idempotent ; le retour arrière remet <code>true</code>, valeur d&#39;avant pour un schéma issu du manifeste).</li></ul><p><strong>3. Pas de vue liste d&#39;API pour les annuaires : deux pages de départ.</strong></p><ul><li>Le profil Collectivité crée les pages <code>elus</code> (« Élus ») et <code>lieux</code> (« Lieux »), publiées d&#39;office comme les autres pages de départ, chacune composée d&#39;un bloc <code>relation_list</code> en source automatique par type (<code>annuaire_elu</code>, <code>annuaire_lieu</code>), sans liste d&#39;identifiants figée, triée par date de publication croissante (l&#39;ordre de saisie), jusqu&#39;à 100 fiches.</li><li><code>ContentSource</code> gagne un drapeau <code>directory</code> : une source automatique en annuaire n&#39;est pas comptée contre le plafond de largeur du manifeste (six cartes à 100 %), qui protège une mise en page en cartes. La borne dure du Core (<code>MAX_SOURCE_LIMIT</code>, 100) reste opposée. Une liste sans <code>directory</code> garde son plafond.</li><li>Chaque élément d&#39;un bloc <code>relation_list</code> porte un <code>summary</code> : le résumé de la décision 1 plus <code>fonctions</code>, <code>delegations</code>, <code>image</code> (identifiant du premier champ média public, dont les métadonnées sont ajoutées à <code>media</code> de la page), <code>horaires</code>, <code>telephones</code>, <code>courriels</code> (<code>[{intitule, courriel}]</code>), <code>site_web</code>, <code>reseaux</code> (<code>[{reseau, url}]</code>, liens de réseaux sociaux en http(s), dans l&#39;ordre de déclaration). Règle générique : un champ de coordonnées <strong>public</strong> est servi, un champ non public jamais — le courriel et les réseaux d&#39;un élu le sont, son téléphone et son adresse ne le sont plus (décision n°2).</li><li><code>GET /public/forms?organization_id=…</code> liste les démarches <strong>ouvertes</strong> de l&#39;organisation (un <code>form_config</code> dont <code>enabled</code> n&#39;est pas faux), triées par titre, bornées à 200, sous une limite de débit nommée (<code>RATE_LIMIT_PUBLIC_FORMS_LIST_PER_IP</code>), avec le même 404 pour une organisation ou un site inconnu. Chaque élément : <code>{key, title, description, path}</code>. Il ne porte ni champs ni captcha.</li></ul><p><strong>4. L&#39;agenda s&#39;exporte en iCalendar : un événement, ou tout l&#39;agenda.</strong></p><ul><li>Le bouton « Ajouter à mon agenda » reste la route <code>.ics</code> existante d&#39;un événement.</li><li><code>GET /listings/{clé}/ical?organization_id=…&amp;site_id=…</code> sert un flux d&#39;abonnement : les événements <strong>à venir et en cours</strong> visibles du public, triés par date de début, bornés à 500, dans un seul <code>VCALENDAR</code> nommé du nom du site (<code>X-WR-CALNAME</code>), avec le même <code>ical_config</code>, les mêmes <code>UID</code> et le même 404 « capacité non déclarée » que l&#39;export d&#39;un événement. Limite de débit nommée (<code>RATE_LIMIT_ICAL_FEED_PER_IP</code>), cache public de 60 s comme le flux RSS.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Une vue liste d&#39;API pour l&#39;annuaire des lieux et celui des élus (<code>listing_config</code>)</td><td>Contredit le corpus (« ni vue liste, ni vue détaillée » pour les lieux, composition à la main pour les élus) et créerait deux surfaces pour un même contenu, avec leur tri, leur pagination et leur flux RSS à maintenir. Les pages composées avec le bloc existant donnent l&#39;annuaire sans nouvelle route.</td></tr><tr><td>Laisser le front résoudre chaque relation par un appel par cible</td><td>Un appel par lieu et par événement (N+1), et aucune route publique ne lit un lieu.</td></tr><tr><td>Inclure toute la fiche de la cible dans la réponse</td><td>Servirait des champs que le visiteur n&#39;a pas demandés, dont des coordonnées. Un résumé de six clés suffit à une carte.</td></tr><tr><td>Relever le plafond de six cartes de <code>relation_list</code> à 100 pour tous les blocs</td><td>Fait sauter une règle de mise en page du CDC pour tous les usages. Le drapeau <code>directory</code> limite l&#39;exception aux annuaires.</td></tr><tr><td>Un mécanisme générique de mise à jour des schémas par version de manifeste</td><td>Plus large que ce lot (réconciliation, conflits avec les schémas modifiés par un webmaster, incrément de <code>schema_version</code>). Une migration ciblée, idempotente et réversible suffit ici ; un tel mécanisme mérite son ADR.</td></tr><tr><td>Un flux iCal par abonnement saisi à la main côté front</td><td>Le front ne peut pas borner ni filtrer les événements visibles sans relire toute la liste.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un front écrit le lieu d&#39;un événement, l&#39;annuaire des élus et celui des lieux, la liste des démarches et le bouton d&#39;abonnement avec ce que l&#39;API lui rend, sans second appel par fiche.</li><li>Le front n&#39;a pas à connaître les règles de visibilité : la cible d&#39;une relation est servie ou ne l&#39;est pas, comme la fiche.</li></ul><p><strong>Négatives</strong></p><ul><li>Le bloc <code>relation_list</code> rend toujours, dans <code>entries[].data</code>, les champs publics de chaque fiche, y compris le courriel et les réseaux d&#39;un élu (comportement du bloc depuis l&#39;Epic E2 : seuls les champs <code>public=False</code> sont retranchés ; le téléphone et l&#39;adresse d&#39;un élu en sont donc absents). Le thème lit <code>summary.courriels</code> et <code>summary.reseaux</code>, puis <code>data</code> en repli, et n&#39;affiche jamais un téléphone ni une adresse d&#39;élu.</li><li>Un annuaire s&#39;arrête à 100 fiches, sans pagination ni indication de troncature.</li><li>L&#39;éditeur de pages de l&#39;administration ne connaît pas encore <code>directory</code> : une page d&#39;annuaire réenregistrée par un éditeur qui ne le renvoie pas retrouve le plafond de six cartes.</li><li>Le flux d&#39;abonnement ne résout aucune relation : un événement rattaché à un lieu de l&#39;annuaire n&#39;a pas de <code>LOCATION</code>.</li><li><code>GET /listings/{clé}/ical</code> n&#39;est pas sous <code>/api/v1/public/</code> : la pile de production ne l&#39;expose pas, un site qui l&#39;offre à ses visiteurs doit le relayer.</li><li>Les relations déclarées dans un répéteur ne sont pas résolues, comme elles ne sont pas validées à l&#39;écriture (<code>app/content/relations.py</code>).</li><li>Les blocs de page autres que <code>relation_list</code> ne résolvent pas les relations de leurs éléments.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Relations résolues dans <code>GET /public/resolve</code> et <code>GET /listings/{clé}</code> : <code>apps/api/app/content/summaries.py</code>, testées par <code>apps/api/tests/test_relations_resolues.py</code> (10 tests : cible publiée, six cas de cible non publique, autre type, autre organisation, relation multiple, une seule requête quel que soit le nombre de cibles, liste paginée). <strong>Fait le 08/10/2026</strong> (lot 15).</li><li>[x] Champ <code>delegations</code> d&#39;<code>annuaire_elu</code> et migration 0051, testés par <code>apps/api/tests/test_delegations_des_elus.py</code> (organisation nouvelle, schémas existants standard, personnalisé, saisi à la main, retour arrière refusé). <strong>Fait le 08/10/2026</strong>.</li><li>[x] Courriel et réseaux sociaux d&#39;un élu publics et affichés (fiche et carte d&#39;annuaire), téléphone et adresse non publics : <code>test_pages_elus_et_lieux.py</code>, <code>test_delegations_des_elus.py</code>, <code>apps/front/tests/unitaires/lot15.test.ts</code>, lanceur a11y. <strong>Fait le 08/10/2026</strong> (décision du Product Owner du 08/10).</li><li>[x] Pages <code>elus</code> et <code>lieux</code> du profil Collectivité, <code>ContentSource.directory</code> et <code>summary</code> des éléments : <code>apps/api/tests/test_pages_elus_et_lieux.py</code> (7 tests), <code>apps/api/tests/test_profiles.py</code>. <strong>Fait le 08/10/2026</strong>.</li><li>[x] <code>GET /public/forms</code> : <code>apps/api/tests/test_demarches_publiques.py</code> (9 tests : ouvertes seulement, tri, borne, 404 unique, limite de débit). <strong>Fait le 08/10/2026</strong>.</li><li>[x] <code>GET /listings/{clé}/ical</code> : <code>apps/api/tests/test_flux_ical_agenda.py</code> (12 tests : à venir et en cours, tri, borne, visibilité, 404, format RFC 5545, limite de débit). <strong>Fait le 08/10/2026</strong>.</li><li>[x] Front : rendre <code>relations</code> (lieu d&#39;un événement), les pages Élus et Lieux en annuaire à partir de <code>summary</code>, la liste des démarches par <code>GET /public/forms</code> et le bouton d&#39;abonnement à l&#39;agenda. <strong>Fait le 08/10/2026</strong> : thème Collectivité (<code>apps/front/themes/collectivite/</code> : <code>FicheEvenement</code>, <code>BlocListeAnnuaire</code>, <code>LiensElu</code>, <code>ListeDemarches</code>, <code>ListeAgenda</code>), relais iCal <code>apps/front/server/api/site/ical/</code>, <code>tests/unitaires/lot15.test.ts</code>, <code>npm run test:a11y</code> (pages /elus, /lieux, /demarches, événement avec lieu, fiche élu, relais <code>text/calendar</code>).</li><li>[x] Exploitation : déclarer <code>RATE_LIMIT_PUBLIC_FORMS_LIST_PER_IP</code> et <code>RATE_LIMIT_ICAL_FEED_PER_IP</code> dans <code>deploy/compose.yml</code> (avec les autres <code>RATE_LIMIT_…</code>), et relayer <code>/api/v1/listings/{clé}/ical</code> si le site propose l&#39;abonnement. <strong>Fait le 08/10/2026</strong> : les deux variables sont déclarées dans <code>deploy/compose.yml</code> ; le flux et l&#39;export par événement passent par le relais du front, qui joint <code>cms-api</code> par le réseau interne de la pile.</li><li>[x] Administration : faire connaître <code>directory</code> à l&#39;éditeur de pages (bloc « Liste de contenus »). <strong>Fait le 08/10/2026</strong> : case « Afficher en annuaire » en mode automatique (<code>apps/admin/components/pagebuilder/PageContentSource.vue</code>), retirée au passage en mode manuel ; <code>directory</code> dans <code>types/api.ts</code> et <code>defaultContentSource()</code>.</li></ul>',23)])])}const g=s(n,[["render",a]]);export{m as __pageData,g as default};
